+          tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted);">No audit logs.</td></tr>';
+          return;
+        }
+        tbody.innerHTML = audits.map(a => {
+          let badgeClass = 'badge-primary';
+          if (a.action_type.includes('create')) badgeClass = 'badge-success';
+          if (a.action_type.includes('approve')) badgeClass = 'badge-success';
+          if (a.action_type.includes('decline') || a.action_type.includes('delete')) badgeClass = 'badge-danger';
+          if (a.action_type.includes('update') || a.action_type.includes('edit')) badgeClass = 'badge-warning';
+          
+          return `
+            <tr>
+              <td style="font-family: monospace; font-size: 0.8rem; white-space: nowrap;">${new Date(a.timestamp).toLocaleTimeString()}</td>
+              <td><span class="badge" style="background-color: rgba(255,255,255,0.05);">${escapeHtml(a.actor_name)} (${escapeHtml(a.actor_type)})</span></td>
+              <td><span class="badge ${badgeClass}">${escapeHtml(a.action_type)}</span></td>
+              <td><span class="badge badge-info">${escapeHtml(a.entity_type)} #${a.entity_id}</span></td>
+              <td>${escapeHtml(a.summary)}</td>
+            </tr>
+          `;
+        }).join('');
+      }
+
+      function escapeHtml(str) {
+        if (!str) return '';
+        if (typeof str !== 'string') return String(str);
+        return str.replace(/&/g, '&amp;')
+                  .replace(/</g, '&lt;')
+                  .replace(/>/g, '&gt;')
+                  .replace(/"/g, '&quot;')
+                  .replace(/'/g, '&#039;');
+      }
+
+      // Initialize page
+      restoreStateFromURL();
+      fetchListings();
+      loadSavedSearches();
+    });
+  </script>
